import {sourceDetails,familyMap,parentChoices} from '../shared/ancestry-ui.js?v=0.20.0';
import {hasDescendants} from '../shared/ancestry.js?v=0.20.0';
import {markdown as familyMarkdown} from '../family/state.js?v=0.20.0';
import {boot,e,field,editAttrs} from '../creative-kit/ui.js?v=0.20.0';
import {make,validate,apply,markdown,METHODS,ENTRIES,ENTRY_METHODS,CONCERN_FIELDS,DESIGN_FIELDS,SIDE_FIELDS} from './state.js?v=0.20.0';
import {parseImport,legacySession,migrate} from './import.js?v=0.20.0';
const prompts={first:'What would you try first? Make the mechanism concrete.',refine:'Which part could work differently while the main mechanism stays?',different:'What could replace the mechanism rather than polish it?',need:'Could the concern disappear because this requirement is no longer needed?',delivery:'Could the benefit arrive through a different channel, moment or actor?',exposure:'Could a smaller scope, limit or reversible trial contain the concern?',context:'Under which observable conditions would each approach make sense?',sequence:'Could one approach create the conditions for the other?',invent:'What different mechanism might protect both useful intentions?'};
const labels={title:'Alternative name',mechanism:'How does it work?',benefit:'What benefit does it retain or create?',cost:'What cost or unresolved concern remains?',difference:'What is different about the mechanism?',assumptions:'What has to be true?',evidence:'What evidence do you have or still need?',boundary:'Where does this approach fit — and where does it stop?',assessment:'How does it fare against your criteria?',test:'Smallest useful test',learn:'What result would change your mind?',reason:'Why make this branch?',ingredients:'Which ingredients or components does it use?'};
const sideLabels={proposal:'The proposed approach',benefit:'The useful intention it protects',context:'When is this a good fit?',cost:'What does it cost or put at risk?',evidence:'What observation could support or challenge it?'};
const show=(value,fallback='Not written yet.')=>e(value||fallback);
const button=(action,id,label,extra='',cls='')=>`<button class="${cls}" data-action="${action}" data-id="${e(id)}" ${extra}>${label}</button>`;
function note(label,value){return `<div class="reasoning"><span>${e(label)}</span><p>${show(value)}</p></div>`;}
function provenance(d){return sourceDetails(d.ancestry);}
function links(w,d){return `<div class="source-links">${d.concerns.map(id=>`<span>Concern: ${show(w.concerns.find(c=>c.id===id).objection)}</span>`).join('')}${d.protects.map(side=>`<span>Protect ${side.toUpperCase()}: ${show(w.sides[side].benefit)}</span>`).join('')}</div>`;}
function card(w,d){return `<article class="card alternative ${w.selected===d.id?'chosen':''}" data-drop-id="design:${e(d.id)}"><div class="card-top"><span>${METHODS[d.method]}${d.ancestry.parked?' · parked':''}</span>${w.selected===d.id?'<span class="tag">To test</span>':''}</div><h3>${show(d.title,'Untitled alternative')}</h3><p class="mechanism">${show(d.mechanism,'Describe how this approach works.')}</p><div class="strength-token" data-drag-id="strength:${e(d.id)}"><div><span>Benefit to keep</span><p>${show(d.benefit,'Name the useful part.')}</p></div><button class="drag-handle" data-drag-handle data-action="borrow-menu" data-id="${e(d.id)}" aria-label="Borrow benefit from ${show(d.title,'this alternative')}">⠿</button></div>${links(w,d)}${d.borrowed.map(b=>`<div class="borrowed"><span>Borrowed from ${show(b.title,'another alternative')}${b.stale?' · source changed':''}</span><p>${show(b.text)}</p></div>`).join('')}${d.stale?'<p class="review-note">Context or connections changed. Check that the mechanism still fits.</p>':''}<details class="reason-details"><summary>Costs, assumptions &amp; differences</summary>${['cost','difference','assumptions','evidence','boundary'].filter(f=>d[f]||['cost','assumptions'].includes(f)).map(f=>note(labels[f],d[f])).join('')}</details>${provenance(d)}<div class="card-actions">${button('develop',d.id,'Develop')}${button('branch',d.id,'Branch ↗','','text-button')}${button('connections',d.id,'Connections','','text-button')}</div><button class="compare-toggle" data-action="compare" data-id="${e(d.id)}" aria-pressed="${w.comparison.includes(d.id)}">${w.comparison.includes(d.id)?'✓ In comparison':'Add to comparison'}</button></article>`;}
function concernBank(w){return `<div class="bank-head"><h2>What does the objection protect?</h2><p>Drop a concern onto a route to create an alternative, or onto an existing card to connect it.</p></div>${w.concerns.map(c=>`<article class="card concern" data-drag-id="concern:${e(c.id)}"><div class="card-top"><span>Concern</span><button class="drag-handle" data-drag-handle data-action="concern-menu" data-id="${e(c.id)}" aria-label="Use concern: ${show(c.objection,'untitled')}">⠿</button></div><h3>${show(c.objection,'State the objection')}</h3><p>${show(c.concern,'What need or risk is underneath it?')}</p><div class="card-actions">${button('edit-concern',c.id,'Clarify','','text-button')}${button('concern-menu',c.id,'Use this concern →','','text-button')}</div></article>`).join('')}<button data-action="add-concern" ${w.concerns.length>=12?'disabled':''}>+ Objection</button>`;}
function sideBank(w){return `<div class="bank-head"><h2>Keep the useful intentions</h2><p>These are positions, not teams to pick between. Drag a benefit onto an alternative, or use Carry benefit.</p></div>${['a','b'].map(side=>`<article class="card position"><div class="card-top"><span>Position ${side.toUpperCase()}</span></div><h3>${show(w.sides[side].proposal,'Describe the proposal')}</h3><div class="strength-token" data-drag-id="benefit:${side}"><div><span>Protect</span><p>${show(w.sides[side].benefit,'What is the intention worth keeping?')}</p></div><button class="drag-handle" data-drag-handle data-action="benefit-menu" data-side="${side}" aria-label="Carry benefit from position ${side.toUpperCase()}">⠿</button></div><details><summary>Context, cost &amp; evidence</summary>${['context','cost','evidence'].map(f=>note(sideLabels[f],w.sides[side][f])).join('')}</details><div class="card-actions">${button('edit-side',side,'Edit position','','text-button')}<button class="text-button" data-action="benefit-menu" data-side="${side}">Carry benefit →</button></div></article>`).join('')}`;}
function generateBank(){return `<div class="bank-head"><h2>Change what makes it work</h2><p>Start anywhere. A useful alternative changes a mechanism, actor, timing or condition—not just its name.</p></div><div class="prompt-note"><h3>Make the difference explicit</h3><p>What must happen for this option to work? What would another option do instead?</p><p>Drag one alternative’s benefit onto another to keep a source snapshot while you work out how to borrow it.</p></div>`;}
function routeChoices(w){return `<div class="route-choices">${ENTRY_METHODS[w.entry].map(method=>`<button data-action="route" data-method="${method}" data-drop-id="method:${method}" ${w.designs.length>=32?'disabled':''}><strong>${METHODS[method]} <span aria-hidden="true">↗</span></strong><span>${prompts[method]}</span></button>`).join('')}</div>`;}
function compare(w){const chosen=w.designs.find(d=>d.id===w.selected);return `<section class="comparison-section"><div class="section-head"><div><h2>Compare mechanisms, not polish</h2><p>Use the same criteria for each option. These are your judgements; there is no generated score.</p></div><button data-action="view" data-view="build">Back to alternatives</button></div><details class="criteria-editor" ${w.criteria?'':'open'}><summary>Compare against${w.criteria?': '+e(w.criteria):' your own criteria'}</summary>${field('criteria','What will make one option preferable?',w.criteria,editAttrs('workspace','','criteria'),'Name the outcomes, constraints or trade-offs that matter.')}</details><details class="compare-picker"><summary>Choose up to four to compare · ${w.comparison.length} selected</summary><div class="toolbar">${w.designs.map(d=>button('compare',d.id,show(d.title,'Untitled'),`aria-pressed="${w.comparison.includes(d.id)}"`)).join('')}</div></details>${w.comparison.length?`<p class="pan-hint">Scroll sideways to compare ${w.comparison.length} alternative${w.comparison.length===1?'':'s'} →</p><div class="comparison-scroll" tabindex="0" aria-label="Alternatives comparison. Scroll sideways."><div class="comparison-grid" style="--columns:${w.comparison.length}">${w.comparison.map(id=>{const d=w.designs.find(d=>d.id===id);return `<article class="comparison-card ${w.selected===id?'chosen':''}"><h3>${show(d.title,'Untitled alternative')}</h3>${['mechanism','benefit','cost','assumptions','difference','boundary','evidence','assessment'].map(f=>note(labels[f],d[f])).join('')}${links(w,d)}${d.borrowed.map(b=>note(`Borrowed from ${b.title}${b.stale?' · source changed':''}`,b.text)).join('')}${d.stale?'<p class="review-note">Recheck the changed context.</p>':''}<div class="card-actions">${button('develop',id,'Develop')}${button('select',id,w.selected===id?'✓ Selected for a test':'Select for a test',`aria-pressed="${w.selected===id}"`)}</div></article>`;}).join('')}</div></div>`:'<p class="empty">Choose alternatives above. They all stay on the board.</p>'}<section class="test-plan"><h2>A decision worth testing</h2><p>${chosen?`Selected: <strong>${show(chosen.title)}</strong>. The other alternatives remain available.`:'Select an alternative to test, or write what you need to learn before choosing.'}</p>${field('decision','What makes this your next move?',w.decision,editAttrs('workspace','','decision'))}${chosen?button('use-test',chosen.id,'Copy this alternative’s test into the plan'):''}${field('test','Smallest useful test',w.test,editAttrs('workspace','','test'))}${field('learn','What result would change your mind?',w.learn,editAttrs('workspace','','learn'))}</section></section>`;}
function render(w){return `<nav class="entry-nav" aria-label="Ways into alternatives">${Object.entries(ENTRIES).map(([entry,label])=>`<button data-action="entry" data-entry="${entry}" aria-pressed="${w.entry===entry&&w.view==='build'}">${label}</button>`).join('')}<button data-action="view" data-view="compare" aria-pressed="${w.view==='compare'}">Compare &amp; test · ${w.comparison.length}</button></nav><div class="workspace-context"><details><summary>Benefit worth keeping${w.benefit?' · '+e(w.benefit):''}</summary>${field('original-benefit','What made this situation worth improving?',w.benefit,editAttrs('workspace','','benefit'))}</details><button class="text-button" data-action="bring-work">Bring earlier work ↑</button></div>${w.source?`<details class="import-source"><summary>Copied from ${sourceName(w.source.kind)} · original retained</summary><p>This is a separate workspace. The original tool and its saved work have not changed. An unchanged source snapshot is included in exports.</p>${button('show-source','','Read the original snapshot','','text-button')}</details>`:''}<div class="ancestry-toolbar"><button data-action="trace-branches">Trace branches</button><button data-action="combine-menu" ${w.designs.length<2||w.designs.length>=32?'disabled':''}>Combine two alternatives</button></div>${w.view==='compare'?compare(w):`<div class="alternatives-layout"><aside class="source-bank">${w.entry==='concerns'?concernBank(w):w.entry==='reconcile'?sideBank(w):generateBank()}</aside><section class="alternatives-board"><div class="section-head"><div><h2>Another way to make it work</h2><p>Choose a route into a new alternative. Every route joins the same collection below.</p></div></div>${routeChoices(w)}<div class="section-head"><div><h2>Your alternatives <span class="count">${w.designs.length}/32</span></h2><p>Develop the mechanism. Branch an idea, borrow a benefit, then compare the trade-offs.</p></div><button data-action="view" data-view="compare">Compare &amp; test →</button></div><div class="alternative-grid">${w.designs.filter(d=>!d.ancestry.parked).map(d=>card(w,d)).join('')||'<p class="empty">Create an alternative or revive one below.</p>'}</div>${w.designs.some(d=>d.ancestry.parked)?`<details class="parked-collection"><summary>Parked alternatives · ${w.designs.filter(d=>d.ancestry.parked).length}</summary><div class="alternative-grid">${w.designs.filter(d=>d.ancestry.parked).map(d=>card(w,d)).join('')}</div></details>`:''}</section></div>`}`;}
function editConcern(id,k){const c=k.w().concerns.find(c=>c.id===id);k.open(CONCERN_FIELDS.map((f,i)=>field(`concern-${f}`,['The objection','The concern beneath it','What observation would support or challenge it?'][i],c[f],editAttrs('concerns',id,f))).join('')+`<div class="toolbar"><button class="primary" data-action="close">Done</button>${button('remove-concern',id,'Remove unused concern',k.w().designs.some(d=>d.concerns.includes(id))?'disabled':'','delete')}</div>`,'Clarify the objection');}
function editSide(side,k){k.open(SIDE_FIELDS.map(f=>field(`side-${f}`,sideLabels[f],k.w().sides[side][f],editAttrs('sides',side,f))).join('')+'<button class="primary" data-action="close">Done</button>',`Develop position ${side.toUpperCase()}`);}
function develop(id,k){const d=k.w().designs.find(d=>d.id===id);k.open(`<p class="hint">${prompts[d.method]}</p>${['title','mechanism','benefit',...(d.ancestry.parents.length?['difference','reason']:[])].map(f=>field(`design-${f}`,labels[f],d[f],editAttrs('designs',id,f))).join('')}<details><summary>Trade-offs, assumptions &amp; comparison</summary>${['ingredients','cost',...(!d.ancestry.parents.length?['difference']:[]),'assumptions','boundary','evidence','assessment'].map(f=>field(`design-${f}`,labels[f],d[f],editAttrs('designs',id,f))).join('')}</details><details><summary>Test this alternative</summary>${['test','learn'].map(f=>field(`design-${f}`,labels[f],d[f],editAttrs('designs',id,f))).join('')}</details>${provenance(d)}<p class="hint">Marking checked keeps any borrowed snapshots as they are. Refresh a borrowed benefit in Connections if you want its latest wording.</p><div class="toolbar"><button class="primary" data-action="close">Done</button>${button('review',id,'Context & connections checked')}${button('connections',id,'Connections')}${button('park',id,d.ancestry.parked?'Revive alternative':'Park alternative')}${button('remove-design',id,'Remove alternative',hasDescendants(k.w().designs,id)?'disabled title="Park this ancestor to preserve its descendants."':'','delete')}</div>`,'Develop the alternative');}
function newDesign(k,method,source={}){const id=k.uid();if(k.act({type:source.concern?'fork':'add-design',id,method,...source}))develop(id,k);}
function concernMenu(id,k){const w=k.w();k.open(`<p>${show(w.concerns.find(c=>c.id===id).concern)}</p><h3>Create an alternative</h3><div class="dialog-options">${ENTRY_METHODS.concerns.map(method=>button('new-from-concern',id,METHODS[method]+`<span>${prompts[method]}</span>`,`data-method="${method}" ${w.designs.length>=32?'disabled':''}`)).join('')}</div><h3 class="dialog-section">Connect an existing alternative</h3><div class="dialog-options">${w.designs.map(d=>button('link',d.id,show(d.title),`data-concern="${e(id)}" ${d.concerns.includes(id)?'disabled':''}`)).join('')||'<p class="hint">No alternatives yet.</p>'}</div>`,'Use this concern');}
function benefitMenu(side,k){const w=k.w();k.open(`<p>${show(w.sides[side].benefit)}</p><h3>Create an alternative</h3><div class="dialog-options">${ENTRY_METHODS.reconcile.map(method=>`<button data-action="new-from-benefit" data-side="${side}" data-method="${method}" ${w.designs.length>=32?'disabled':''}>${METHODS[method]}<span>${prompts[method]}</span></button>`).join('')}</div><h3 class="dialog-section">Carry into an existing alternative</h3><p class="hint">A link records an intention. Explain how the mechanism protects it, then test the claim.</p><div class="dialog-options">${w.designs.map(d=>button('protect',d.id,show(d.title),`data-side="${side}" ${d.protects.includes(side)?'disabled':''}`)).join('')||'<p class="hint">No alternatives yet.</p>'}</div>`,'Carry a useful intention');}
function borrowMenu(from,k){const w=k.w(),d=w.designs.find(d=>d.id===from);k.open(`<p>Keep a snapshot of this benefit in another alternative. Both designs remain.</p>${note('Benefit to borrow',d.benefit)}<div class="dialog-options">${w.designs.filter(d=>d.id!==from).map(d=>button('borrow',d.id,show(d.title),`data-from="${e(from)}"`)).join('')||'<p class="hint">Create another alternative first.</p>'}</div>`,'Borrow a benefit');}
function connections(id,k){const w=k.w(),d=w.designs.find(d=>d.id===id);k.open(`<p>${show(d.title)}</p><h3>Concerns addressed</h3><div class="dialog-options">${w.concerns.map(c=>button(d.concerns.includes(c.id)?'unlink':'link',id,`${d.concerns.includes(c.id)?'✓ ':''}${show(c.objection)}`,`data-concern="${e(c.id)}"`)).join('')||'<p>No concerns written.</p>'}</div><h3 class="dialog-section">Intentions to protect</h3><div class="dialog-options">${['a','b'].map(side=>button(d.protects.includes(side)?'unprotect':'protect',id,`${d.protects.includes(side)?'✓ ':''}Position ${side.toUpperCase()}: ${show(w.sides[side].benefit)}`,`data-side="${side}"`)).join('')}</div><h3 class="dialog-section">Borrowed benefits</h3>${d.borrowed.map(b=>`<div class="borrowed">${note(`From ${b.title}${b.stale?' · source changed':''}`,b.text)}<div class="toolbar">${button('refresh-borrow',id,'Refresh from source',`data-from="${e(b.from)}"`)}${button('unborrow',id,'Remove connection',`data-from="${e(b.from)}"`)}</div></div>`).join('')||'<p>No borrowed benefits. Use a benefit handle on another card to bring one here.</p>'}<button class="primary" data-action="close">Done</button>`,'Connections and source snapshots');}
function sourceName(kind){return {answers:'Three Answers',disagreement:'Disagreement',family:'Family Tree'}[kind];}
function sourceRecord(source){const w=source.workspace;if(source.kind==='family')return `<pre class="source-prose">${e(familyMarkdown(w))}</pre>`;const title=`<p>${show(w.problem)}</p>`;if(source.kind==='answers')return title+Object.entries(w.answers).map(([key,a])=>`<section class="source-part"><h3>${show(a.title,'Untitled alternative')}${w.chosen===key?' · selected':''}</h3>${['mechanism','strength','weakness','difference','assessment'].map(f=>note(f,a[f])).join('')}${a.borrowed.map(b=>note(`Borrowed from ${w.answers[b.from].title}${b.stale?' · source changed':''}`,b.text)).join('')}</section>`).join('')+['criteria','test','learn'].map(f=>note(f,w[f])).join('');return title+['a','b'].map(side=>`<section class="source-part"><h3>Position ${side.toUpperCase()}</h3>${SIDE_FIELDS.map(f=>note(sideLabels[f],w.sides[side][f])).join('')}</section>`).join('')+w.plans.map(p=>`<section class="source-part"><h3>${show(p.title)}${w.selected===p.id?' · selected':''}</h3><p>${METHODS[p.route]}${p.stale?' · context needs review':''}</p>${['mechanism','boundary','cost','test','learn'].map(f=>note(labels[f],p[f])).join('')}${p.protects.map(side=>note(`Intention from position ${side.toUpperCase()}`,w.sides[side].benefit)).join('')}</section>`).join('');}
function bringWork(k){let html='<p>Copy an earlier workspace into Alternatives. Its original remains in its tool, and a source snapshot travels with the copy.</p>';for(const [kind,name] of [['answers','Three Answers'],['disagreement','Disagreement'],['family','Family Tree']]){html+=`<h3>${name}</h3>`;try{const raw=localStorage.getItem(`thinking-lab:${kind}:v1`);const work=raw?legacySession(kind,raw).workspaces:[];html+=`<div class="dialog-options">${work.map(w=>button('copy-legacy',w.id,show(w.problem,'Untitled workspace'),`data-kind="${kind}"`)).join('')||'<p class="hint">No saved work from this tool in this browser.</p>'}</div>`;}catch{html+=`<p>Saved work could not be read here. <a href="../${kind}/">Open ${name}</a> to recover or export it.</p>`;}}html+='<div class="dialog-section"><button class="primary" data-action="import">Import an earlier JSON export ↑</button></div>';k.open(html,'Bring earlier work');}
function combineMenu(k){const w=k.w();k.open(`<form id="combine-form">${parentChoices(w.designs,w.comparison)}<p class="combine-error" role="status"></p><div class="toolbar"><button class="primary" type="submit">Create combined alternative</button><button type="button" data-action="close">Cancel</button></div></form>`,'Combine two alternatives');document.querySelector('#combine-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget,parents=[form.elements['parent-a'].value,form.elements['parent-b'].value];if(parents[0]===parents[1]){form.querySelector('.combine-error').textContent='Choose two different parents.';return;}const id=k.uid();if(k.act({type:'combine',id,parents}))develop(id,k);};}
boot({route:'objections',code:'S07',title:'Alternatives workbench',description:'Generate options, respond to concerns or reconcile proposals. Compare what each mechanism makes possible.',make,validate,apply,markdown,parseImport,render,
 afterRender:k=>{
  // Inline edits intentionally retain focus instead of rerendering; refresh their
  // compact summaries when closing so they never show the previous wording.
  for(const [selector,field,prefix] of [['.criteria-editor','criteria','Compare against'],['.workspace-context>details','benefit','Benefit worth keeping']]){
   const details=document.querySelector(selector);details?.addEventListener('toggle',()=>{if(!details.open)details.querySelector('summary').textContent=prefix+(k.w()[field]?': '+k.w()[field]:'');});
  }
 },
 drop:(source,target,k)=>{const [kind,id]=source.split(':'),[type,to]=target.split(':');if(type==='method'){if(kind==='concern'&&ENTRY_METHODS.concerns.includes(to))newDesign(k,to,{concern:id});else if(kind==='benefit'&&ENTRY_METHODS.reconcile.includes(to))newDesign(k,to,{side:id});else k.toast('Drop this benefit onto another alternative.');}else if(type==='design'){const action=kind==='concern'?{type:'link',id:to,concern:id}:kind==='benefit'?{type:'protect',id:to,side:id}:{type:'borrow',from:id,to};if(k.act(action))k.toast(kind==='strength'?'Benefit snapshot borrowed. Develop how it fits.':'Connection added. Check the mechanism before marking it resolved.');}},
 handle:(a,d,k)=>{
  if(a==='develop')develop(d.id,k);else if(a==='edit-concern')editConcern(d.id,k);else if(a==='edit-side')editSide(d.id,k);
  else if(a==='add-concern'){const id=k.uid();if(k.act({type:a,id}))editConcern(id,k);}
  else if(a==='entry')k.act({type:a,entry:d.entry},{checkpoint:false});else if(a==='view')k.act({type:a,view:d.view},{checkpoint:false});
  else if(a==='route'){if(ENTRY_METHODS.concerns.includes(d.method)){if(!k.w().concerns.length){k.toast('Add an objection first, then choose the concern this route should address.');return;}k.open('<div class="dialog-options">'+k.w().concerns.map(c=>button('new-from-concern',c.id,show(c.objection),`data-method="${d.method}"`)).join('')+'</div>','Which concern opens this route?');}else newDesign(k,d.method);}
  else if(a==='new-from-concern')newDesign(k,d.method,{concern:d.id});else if(a==='new-from-benefit')newDesign(k,d.method,{side:d.side});
  else if(a==='concern-menu')concernMenu(d.id,k);else if(a==='benefit-menu')benefitMenu(d.side,k);else if(a==='borrow-menu')borrowMenu(d.id,k);else if(a==='connections')connections(d.id,k);
  else if(a==='trace-branches')k.open(familyMap(k.w().designs.map(d=>({...d,changed:d.difference})))+'<button data-action="close">Done</button>','How the alternatives developed');
  else if(a==='combine-menu')combineMenu(k);
  else if(a==='branch'){const id=k.uid();if(k.act({type:a,id,parent:d.id}))develop(id,k);}
  else if(a==='borrow'){if(k.act({type:a,from:d.from,to:d.id})){k.close();k.toast('Benefit snapshot borrowed. Explain how the combination works.');}}
  else if(['link','unlink','protect','unprotect','unborrow','refresh-borrow'].includes(a)){const act=a==='refresh-borrow'?{type:'borrow',to:d.id,from:d.from}:{type:a,id:d.id,concern:d.concern,side:d.side,from:d.from};if(k.act(act))connections(d.id,k);}
  else if(['review','park','remove-design','remove-concern'].includes(a)){if(k.act({type:a,id:d.id}))k.close();}
  else if(['compare','select'].includes(a))k.act({type:a,id:d.id});
  else if(a==='use-test'){if(k.act({type:a,id:d.id}))k.toast('Alternative’s test copied into the working plan. Undo restores your previous wording.');}
  else if(a==='bring-work')bringWork(k);
  else if(a==='copy-legacy'){try{const raw=localStorage.getItem(`thinking-lab:${d.kind}:v1`);if(!raw)throw Error('That source is no longer saved here.');const source=legacySession(d.kind,raw).workspaces.find(w=>w.id===d.id);if(!source)throw Error('That source workspace is no longer available.');if(k.act({type:'import',id:k.uid(),workspace:migrate(d.kind,source)})){k.close();k.toast('Copied into a new workspace. The original is unchanged.');}}catch(error){k.toast(error.message);}}
  else if(a==='show-source'){const s=k.w().source;k.open(`<p>Original ${sourceName(s.kind)} workspace, kept exactly as imported.</p>${sourceRecord(s)}<button data-action="close">Done</button>`,'Original source record');}
 }
});
